 pub fn book(&mut self,i:usize,at:u64,bid:&str,ask:&str,n:u64){self.sequences[i]+=1;let seq=self.sequences[i];self.bank.accept(&format!("surface-books-{i}"),seq,&json!({"type":"book","receivedAt":iso(at),"book":{"marketId":(201+i).to_string(),"exchangeId":(101+i).to_string(),"tournamentId":"cup","sequence":seq.to_string(),"sourceAt":iso(at),"requestStartedAt":iso(at),"receivedAt":iso(at),"bids":[{"price":bid,"quantity":n}],"asks":[{"price":ask,"quantity":n}]}})).unwrap();}
